// setWorkspace attaches caller-owned device memory as the handle's workspace.
//
// This function sets the workspace used by the cuStateVec library.
//
// This function sets the workspace attached to the handle.
// The required size of the workspace is obtained by
// [Handle.GetDefaultWorkspaceSize].
//
// By setting a larger workspace, users are able to execute functions without
// allocating the extra workspace in some functions.
//
// If a device memory handler is set, the workspace can be set to null and
// the workspace is allocated using the user-defined memory pool.
//
//   - handle: in the handle to the cuStateVec context
//   - workspace: in device pointer to workspace
//   - workspaceSizeInBytes: in workspace size
//
// Wraps custatevecSetWorkspace.
func setWorkspace(handle Handle, workspace uintptr, workspaceSizeInBytes uint) error {
	if err := checkLibSym("custatevecSetWorkspace"); err != nil {
		return err
	}
	return toError(fnsetWorkspace(handle, workspace, workspaceSizeInBytes))
}
